<script lang="ts">import type {RuntimeTaskEntity} from '../lib/taskRuntimeNavigation.ts';export let task:RuntimeTaskEntity|null=null;export let onViewWorkPackage:(id:string)=>void=()=>{};</script>
{#if task}<section class="runtime-detail-view" data-testid="runtime-detail-view"><div class="section-label"><span>Runtime Detail</span><small>{task.task_id}</small></div><div class="runtime-detail-grid"><div><span>Task ID</span><b>{task.task_id}</b></div><div><span>Execution ID</span><b>{task.execution_id??'NOT_AVAILABLE'}</b></div><div><span>Provider</span><b>{task.provider??'NOT_AVAILABLE'}</b></div><div><span>Runtime Status</span><b>{task.status}</b></div><div><span>HEAD</span><b>{task.head_sha??'NOT_AVAILABLE'}</b></div><div><span>Delivery Context</span><b>{task.delivery_context_id??'NOT_AVAILABLE'}</b></div><div><span>Associated WP</span><b>{task.work_package_id??'NOT_AVAILABLE'}</b></div></div>{#if task.work_package_id}<button class="service-action" onclick={()=>onViewWorkPackage(task!.work_package_id!)}>查看 Work Package</button>{:else}<p>缺少 Work Package Context，无法导航。</p>{/if}</section>{/if}
